additionalExercises.referenceSolution:
#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    std::vector<long long> v;
    long long x;
    while (std::cin >> x) {
        v.push_back(x);
    }
    auto negatives = std::erase_if(v, [](long long value) { return value < 0; });
    std::sort(v.begin(), v.end());
    std::size_t before = v.size();
    v.erase(std::unique(v.begin(), v.end()), v.end());
    std::cout << "отрицательных: " << negatives << '\n';
    std::cout << "повторов: " << before - v.size() << '\n';
    std::cout << "осталось:";
    if (v.empty()) {
        std::cout << " пусто";
    }
    for (long long value : v) {
        std::cout << ' ' << value;
    }
    std::cout << '\n';
    return 0;
}

